INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1088184-econ102', 'stk-s.a.l.m.a.n', 'ECON 102', 'info', '{"desc": "^^^^\n\n+1\n\n… الكورس بالنسبة لي كان جدا ممتع ومفيد اكثر من 101 , الكتاب المستخدم سهل الفهم , بمجرد المذاكره منه وقراءة الامثله اللي يقدمها بالتفصيل لتوضيح النقطه راح تفهم الكونسيبت بإذن الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-102-principles-of-economics-ii-macroeconomics/121028/4", "user": "S.a.l.m.a.n", "ts": 1346993162000, "tid": 121028, "pn": 4}}', 1346993162000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1340892-econ102', 'stk-practice', 'ECON 102', 'info', '{"desc": "المادة بشكل عام اصعب من 101\n\nالكتاب جدا سيء\n\nما افادني ولا في شي\n\nوحاجات 102 تعلمتها في ايكون206 و 305\n\nالله يعينكم على ذي المادة كل ما سألت احـد قال ادور الـ d", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-102-principles-of-economics-ii-macroeconomics/121028/5", "user": "Practice", "ts": 1394712440000, "tid": 121028, "pn": 5}}', 1394712440000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1341353-econ102', 'stk-blake', 'ECON 102', 'info', '{"desc": "حاليا اسمها اتغير من 202 ل 102\n\nالاقتصاد الكلي\nكورس رائع جدا وممتع لأقصى درجة لسببين رئيسية\n1- كورس يشرحلك العالم من حولك بمنظور الاقتصاد + يلمس الواقع السياسي والمالي بشكل جبار وقوي\n2- كل شي سواء من نظرية او قانون وغيرها يتم اسقاطها عمليا وتطبيقها سواء عبر قصة تشرحها او عبر بيانات ومعلومات حقيقية ومحدثّة\n\nالكورس مهم جدا جدا لطلاب الادارة عموما والفاينانس خصوصا\n\nمن ناحية الصعوبة فهو تقريبا اصعب كورس من كورسات الايكون ولكن من وجهة نظري امتعهم واكثرهم فائدة\n\nوالكتاب الجديد المستخدم رااااااااائع …انا قرأت الكتاب كامل صفحة صفحة ووالله استفدت استفادة غير طبيعية واقدر اقولك لو قرأت الكتاب مزبوط تقدر بالراحة تجيب A+ ويغنيك تماما عن الدكتور .\nمن المميزات في الكتاب نهاية كل شابتر في قصة تطبيقية او حالة دراسية + الكتاب لغته سهلة نسبيا وتصميمه جذاب + الكتاب مدّعم بكمية احصائيات وفوائد جانبية واشياء اخرى كثيرة تفيد وتساعد في فهم المنهج الصعب للمادة\n\nالحمد لله مجموعي النهائي كان Above 90\nكون اغلب طلاب الادارة مستواهم متوسط إلى سيئ وكونهم مايحبو المذاكرة + المادة يبغالها فهم وقراءة هو السبب الرئيسي ان الكل يسب المادة والغالبية العظمى بين ال F وال C\n\nاعيد واكرر مرة ثانية المادة ثقيلة وتتعب وصعبة\nلكن اذا تحب وتعشق الايكون فهذي راح تكون افضل وامتع مادة\nبالإضافة الى انو اذا فهمتها واستوعبتها راح ترتاااااااااااااح كثييير في بقية مواد الايكون لانها تعتمد عليها\n\nاذا نزلت المادة عند دكتور ممتاز ومع وجود الكتاب … المغفل مع احترامي الي يجيب اقل من B", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-102-principles-of-economics-ii-macroeconomics/121028/6", "user": "blake", "ts": 1394819676000, "tid": 121028, "pn": 6}}', 1394819676000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1429218-econ102', 'stk-user10207', 'ECON 102', 'info', '{"desc": "ECON 102 - Term 142\n\n- الكورس يتكلم عن الإقتصاد الكلي Macroeconomics.\n- المواضيع الي في الكورس:\n\n- قياس إجمالي الناتج المحلي GPD.\n- الدورة الإقتصادية (دورة الأعمال).\n- النمو الإقتصادي.\n- التضخم.\n- البطالة.\n- الطلب الكلي\n- العرض الكلي.\n- السياسة المالية.\n- السياسة النقدية.\n- الصناعة المصرفية.\n- صناعة الأموال.\n- أسعار الفائدة.\n- أسعار العملات.\n- ميزان المدفوعات.\n- الفائض التجاري.\n- العجز التجاري.\n\n- الكتاب كان سيء. لكن تم تغييره هذا السمستر 151.\n- المادة أصعب من ECON 101.\n- المادة تحتاج متابعة أول بأول.\n\nبالتوفيق.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-102-principles-of-economics-ii-macroeconomics/121028/7", "user": "user10207", "ts": 1443288651000, "tid": 121028, "pn": 7}}', 1443288651000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1429316-econ102', 'stk-azooz_jk', 'ECON 102', 'info', '{"desc": "ااولا الكتاب اعتقد تغير\n\nلكن المادة جميلة وومتعة وراح تفهم اشياء اقتصادية في الحياة والعالمـ . تحتاج متابعة اول باول\n\nلو مافهمت شيئ لا من الدكتور ولا من الكتاب دور على كورسات مجانية اونلاين\n\nحاليا يدرسها اعتقد القحطاني انصصصح فيه وبقوة !!\nالعبندي للاسف جدا سيئ لو عندو ذاكر اي شيئ بره المنهج وركز عليه !\n\nبالتوفيق !", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-102-principles-of-economics-ii-macroeconomics/121028/8", "user": "Azooz_Jk", "ts": 1443583500000, "tid": 121028, "pn": 8}}', 1443583500000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p25521-econ102', 'stk-user447', 'ECON 102', 'info', '{"desc": "كاتب الرسالة الأصلية بو حميد\nالسلام عليكم ورحمة الله وبركاته,\n\nانا طالب خريج وعندي ECON 202 مع الدكتور أسامة عثمان وانا حضرت اول محاضره واحس ان الرجال فاهم وحبيب بس كثيرين ذموه.\nانا اعرف ان الطلاب مستواهم ماهو واحد وتحصل مشاكل بين الطالب والدكتور فودي أعرف راي الشباب بصراحة عن الدكتور من حيث العدل في الدرجات والدرجة النهائية (Grade) بغض النظر عن هذي المشاكل.\nوللعلم انه يوجد شعبتين غير هذي الشعبة , شعبة عند الحجي وتقريبا مسكر السكشن والثاني عند يماني وفيه مجال كبير , الرجاء تعطونا رايكم بسرعة.\n\nشاكرين تعاونكم\n🙄 🙄 🙄 🙄 🙄", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-202/22919/1", "user": "user447", "ts": 1057079202000, "tid": 22919, "pn": 1}}', 1057079202000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p843218-econ102', 'stk-user5374', 'ECON 102', 'info', '{"desc": "طيب الواجبات كيف تحلها وانت ما فتحت المنهج ؟\nالواجبات عليها 30 % ( كل اسبوع شابتر ) …\n\nوالفاينل من 8 + 9 ( نسبة بسيطه من الاسئلة - اقل من عشرة بالمية )\n+ ( 10 - 11 - 12 - 13 - 14 - 15 - 17 - 20 ) ، احتمال بنسبة ثمانين بالمية يحذفون شابتر 18 …\n\nمن ناحية هل بتواجهك صعوبة ؟\nنعم لكن شيء خفيف ، من 10 الى 15 الدروس كلها لها علاقة مع بعض …\nيعني لازم تستحضر اللي قبل وتبدأ دراسة الشابتر الجديد اذا ودك تفهم 100 %\nويمديك تبدأ الفصل الجديد بدون اللي قبله ، لكن لايستحسن .\nبس تبي الصراحة ؟\nرغم ان الكتاب فيه هرجٍ كثير الا ان المعلومات اللي تحتاجها للاختبار تقدر تلخصها في خمس سطور لكل صفحة …\n\nنصيحتي اذا انت تذاكر من الكتاب …\nاخذ لك قلم تظليل ( يفضل لونين ) .\nhttp://banhoh.com/bmz_cache/9/9793a154497509865febcab24058128b.image.150x112.jpg\nطبعاً كل فصل في الكتاب له عناوين رئيسية تحصلها في بداية الصفحه ملونة باللون الأزرق ، ولها عناوين فرعية ملونة في الكتاب باللون البني …\n\nبعد قراءة كل عنوان فرعي كاملاً ، ابدأ ظلل السطور المهمة الا ان تنتهي من الفصل كاملاً …\nقبل الفاينل مايحتاج تقرأ الفصل من جديد ، وتذاكر من اللي انت مظلله وبس …\nواذا فيه معلومة فهمتها لكن فيها صعوبة وتحس انك بتنساها بعدين … اشرحها بالعربي على جانب الصفحة 🤠\n\nمـدري كم منزل ساعه عشان اشوف يمديك ولا لا ؟\nلكن بالنسبة لي ، قرائتي لكل فصل تستغرق متوسط 4 ساعات ( مع تظليل وشرح على الجانب + تنظيف المكتب والهروب من الغرفه 🤠)\nطبعاً قرائتي بطيئة للإنجليزي ، يمكن انت افضل واسرع …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-202/107447/5", "user": "user5374", "ts": 1305114597000, "tid": 107447, "pn": 5}}', 1305114597000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p843647-econ102', 'stk-naif_m', 'ECON 102', 'info', '{"desc": "يمديك و بالراحة بعد\n\nانا سالت الدكتور قالي ركز ع المعلومات الرئيسية\n\nيعني بشكل عام مافي شي سهل و لا في شي صعب\n\nع العموم اقرا الكتاب مرتين مره الحين و مره قبل الفاينال\n\nو ركز ع الكالكيوليشن و القوانين الموجودين في الكورس كامبس\n\nالكتاب قليلة القوانين اللي فيه\n\nو لا تنسى تراجع عن طريق الستدي بلان و ال سامبل تيست\n\nو بالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-202/107447/7", "user": "Naif_M", "ts": 1305219834000, "tid": 107447, "pn": 7}}', 1305219834000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p896944-econ102', 'stk-real-4-ever', 'ECON 102', 'info', '{"desc": "التي بي ليس هو الحل…!!!!\n\nأخوي أنا ما أنصح بالإعتماد على التي بي لأنه مواد الإيكون مهم جداًإنك تفهم المادة من خلال الشرح وقرأت الكتاب. فهي مادة مرتبطة مفاهيمها الأساسية بجميع تخصصات الأخرى في الكلية. صحيح التي بي ممكن يساعدك تعدي كورس ولا كورسين، لكنه ممكن ويبعدك عن الفهم الحقيقي للموضوع وينكبك في مواد التخصص الأخرى قبل التخرج.\n\nوالله يوفق الجميع 👍", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ202/111352/3", "user": "Real-4-Ever", "ts": 1315529701000, "tid": 111352, "pn": 3}}', 1315529701000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1120258-econ102', 'stk-faisal-fin', 'ECON 102', 'info', '{"desc": "فعلا هالسنة كود جديد و كتاب جديد للمادة\n\nعموما اتمنى انك تكون جالس تاخذ الكورس مع اقدم لانه يعطي طابع ممتع اكثر من العبندي للكورس\n\nهنا وصف للكورس بشكل مبسط\nhttp://skfupm.kfupm.edu.sa/vb/showthread.php?t=81551\n\nطريقة الاختبارات اتفق معاك غبية تماما وما تتناسب مع كورس نظام القريدات فيه ستاندرد\nواقدم عارف هالشيء كويس لكن مصمم يحافظ على الطريقة العالمية لأختبارات الأيكون يلي الجامعة ماخذه الاعتماد العالمي عليه وبالمناسبة قريدات الطلاب السمتسر الماضي ويلي قبله جدا سيئة\n\nكل نصحيتي انك تعطي المادة وقت مناااسب قبل الميجر بفتره تبدا فيها شابتر شابتر والتيست بانك يلي فوق صحيح ماتجي منه اسئلة لكن مفييد جدا انه يعمق فهمك للمنهج وهذا اكبر تحدي في اسئلة مياجر الماكرو وتلاحظ هالشيء لما يستخدمون All of the above , non of the above في اغلب اسئلة الملتبل تشويس", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-102/135002/5", "user": "Faisal-FIN", "ts": 1353357374000, "tid": 135002, "pn": 5}}', 1353357374000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p645033-econ102', 'stk-kitkat', 'ECON 102', 'info', '{"desc": "الدكتور على كلام زميل لي درس عنده 202 …\n\nيقول الدكتور ممتاز جدا من ناحية الشرح … ويعطي كويزات متوسطة الصعوبه الى سهله تركز على الفهم …\n\nبسمستر 092 كنت مع اقدم … الميدتيرم كنت خايف قبل الاختبار … كلمني خويي وقال انه رحمان ارسل لنا ميد تيرم قديم قال راجعوه … وراجعته وفهمته والحمد الله جبت درجه حلوه بالميدتيرم …\n\nوالفاينل نفس الشي ارسل لهم فاينل قديم … ما ذاكرت الا هو وفهمت كل سؤال وكل نقطه بالاختبار … والفانيل جانا 80% من الفاينل اللي ارسله رحمان لطلاب سكشنه قبله بكم يوم بس تغيير ارقام …\n\nزبدت الكلام انه الدكتور يخاف على طلابه ويهتم فيهم … ويبيهم يطلعون بقريدات … وشرحه ممتاز لانه عنده خبره بأمريكا على ما اعتقد … يعني راح تستفيد منه وان شاء الله راح تطلع بقريد …\n\nوالله ولي التوفيق …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-202-m-rahman/78458/6", "user": "KiTKaT", "ts": 1277623424000, "tid": 78458, "pn": 6}}', 1277623424000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1021675-econ102', 'stk-abo.saud', 'ECON 102', 'info', '{"desc": "بصراحة العربي والاسلامي بالنسبة لي اشوف انها مثل الـ PE حضور وذاكر بيوم الاختبار او قبله\nاذا بتحذفهن حط مكانهن مادة ٣ ساعات ولا بصير جدولك شبه فاضي\nالايكون المادة اسهل من الـ 101 & econ 102 عموما ماهي صعبة\nجدولك حاليا ما اشوف فيه شي صعب الا الستات والاكاوتنق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/124162/4", "user": "abo.saud", "ts": 1334319388000, "tid": 124162, "pn": 4}}', 1334319388000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-waleedx11-econ102', 'stk-waleedx11', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f98251", "n": "Dr. Mohsen Al-Hajji", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON102 TERM 162\n\nالتحضير : نهاية الكلاس وبعض المرات ياخذ دقايق إضافية على الكلاس فما يحضر ويطلعنا.\n\nطريقة الشرح : جداً ممتاز ماشاء الله عليه يعيد المعلومة أكثر من مرة علشان الطلاب يفهموا و ممكن هذا الشيء اللي يخلي الطلاب تقول عنه إنه ممل ويجيب النوم ، ولكن شرحه رائع.\n\nالكويزات: 3 كويزات كان المفترض ناخذ رابع بس مع التقديمات اللي صارت أخذنا بس ثلاثة ، مجموعها 15% من المادة و يعطيه العافية حذف أسوأ واحد وأخذ آفرج الاثنين الباقيين.\n\nالمياجر: ملتبل تشويس تقريباً 27 بعدين الباقي ريتن ،، غالباً تجي من النقاط اللي يكتبها وينوه عليها بالكلاس علشان كذا نصيحة أكتب معه كل شيء.\n\nالفاينلات : ( Comprehensive ) نفس مستوى المياجر اللهم كان 50 ملتبل تشويس شامل لكل المنهج بدون ريتن.\n\nالقريد النهائي: الدكتور أعطيه A نظراً لشرحه الممتاز وأعادته للنقطة أكثر من مرة علشان الطلاب يستوعبوا الفكرة بشكل صحيح.\n\nالصوت: واضح وانجليزيته ممتازة.\n\nإضافات :\n1- الدكتور من يخش الكلاس ما يحب أحد يكلم اللي جنبه ، لذلك لا تتكلم علشان ما يهزأك 😂.\n2- الجوال الجوال الجوال ثم الجوال ، اذا شافك مطلع جوالك في الكلاس والله ياهو بيهزىء فيك فانتبه.\n3- لما يسلمكم أوراق المياجر أو الكويزات لا تناقشه إلا في شيء ممكن يكون ظلمك فيه غير كذا برضو راح يهزأك ههههههههههههههه.\n4- أفضل الخيارات الموجودة في قسم الاقتصاد هو و أبوبكر ديالو. لذلك لو حصلت لك الفرصة خذ معه وما بتندم إن شاء الله.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1473903-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohsen-al-hajji/98251/13", "user": "waleedx11", "ts": 1495885514000, "tid": 98251, "pn": 13}}]}', 1495885514000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9921-econ102', 'stk-user9921', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f98251", "n": "Dr. Mohsen Al-Hajji", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 162 Econ 102\nالتحضير :\nفي بداية الترم كان بحضّر أول الكلاس وما يحضر المتأخرين ، بعدها بفترة صار يحضّر في الأخير أو ما يحضّر\n\nطريقة الشرح :\nيشرح على السبورة وساحب على السلايدات ، لازم تروح كلاسه وأنت مصحصح تماماً وشبعان نوم عشان تركيزك معاه ما يضيع ، يشرح من أول إلى آخر دقيقة ويمكن يزيد ،،\nلازم تنتبه لشرحه وتكتب نوته معاه لأن كل مياجره وكوزاته من نوتة شرحه\n\nالكويزات :\nكان بيعطينا ٤ كوزات بس ما أمداه الوقت وعطانا ٣ وحذف واحد ، طبعاً الكويزات مفاجِئة !\n\nالمياجر:\nمياجره تعتمد على فهمك بس إذا شاف الأفرج عالي في الاول يصلخ في الثاني والعكس صحيح\n\nالفاينلات :\nكان كومن\n\nالقريد النهائي: C\n\nإضافات :\nالدكتور كشرح ممتاز ، بس فيه مشكلة أنه يحاول ينزل الأفرج تحت ٧٠ عشان قريداته ما تصير ستاندرد ، في الميجر الاول كان الافرج عالي والميجر الثاني جاب أشياء ما تنحل ،هذا غير الكوزات المفاجئة اللي كل واحد عليه 5 %\n\nفي النهاية الكورس صار ستاندرد وما همه الصلخ اللي سواه معانا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474108-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohsen-al-hajji/98251/14", "user": "user9921", "ts": 1496130975000, "tid": 98251, "pn": 14}}]}', 1496130975000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faris_alali-econ102', 'stk-faris_alali', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f98251", "n": "Dr. Mohsen Al-Hajji", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON102-181\n\nالتحضير : حضر أول اسبوعين و بعدها ما اهتم للتحضير مع ان يدري في غياب يوصل بالراحة لعشرة طلاب لكن متغاضي عنهم , طبعا الي يغيب عنده خسراااان\n\nالشرح : يكتب عالسبورة كل شي مهم و يعيد عشرطعش مرة و مليون قراف اهم شي تفهم لكن لا تقوله بطلع جوالي و بصور لانه بيستجن و بيسفل فيك و بيقولك جيب نوتة و اكتب زي الباقي\n\nالكويزات : اختبرنا 6 و كنسل اسوأ واحد , اغلبه خيارات لكن في كذا كويز فيه رتن و عادي يجيب اشياء ما شرحها لكنها موجودة فالكتاب لذلك لا تعتمد فقط على النوتة لازم تقرأ الكتاب\n\nالمياجر و الفاينل : كومن ( 50 سؤال خيارات و صح أو خطأ )\n\nالواجب : مقارنة بالدكانرة الثانية فضل الحق و اكايما يطلع جنة واجبه جدا بسيييييط يعطيك اسئلة في ورقة و يقولك حلهم و جيبهم في اليوم الفلاني و طبعا واجب واجد بس\n\nالقريد النهائي: A+ بلا شك و خله خيااااااااارك الاول فالكورس ذا لأنه اسطورة حقا و حقيقة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504079-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohsen-al-hajji/98251/15", "user": "Faris_Alali", "ts": 1545775431000, "tid": 98251, "pn": 15}}]}', 1545775431000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kbsc-econ102', 'stk-kbsc', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f98251", "n": "Dr. Mohsen Al-Hajji", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : *\n\nالحجي\n\nالمادة: *\n\nECON 102\n\nطريقة الشرح : *\n\nشرح في السبورة، يشرح بالتفصيل ويعيد ويكرر وافضل شيء تكتب في نوت معه اول بأول لأن اسئلته تجي من النوت حقه.\n\nالكويزات :\n\nمتوسطه وتجي اسئلة من الشرح حقه\n\nالمياجر/ميد:\n\nكومون\nالفاينل :\n\nكومون\n\nطريقة التحضير :\n\nفي البداية كان يحضر، بعدين بدأ يسحب شوي شوي\n\nالقريد النهائي الخاص بك :\n\nA+\nاضافات:\n\nدكتور شديد في التعامل، ويشرح من قلبه، لازم تركز معه. والكتاب الكتاب الكتاب، هو اللي بيخليك تجيب قريد ان شاء الله.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1507363-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohsen-al-hajji/98251/16", "user": "KBSC", "ts": 1552817105000, "tid": 98251, "pn": 16}}, {"id": "stk-dr-f180465", "n": "Dr. Mohammad Akimaya", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : *\n\nمحمد اكمايا\n\nالمادة: *\n\nEcon102\n\nطريقة الشرح : *\n\nيشرح من سلايدات هو مسويها الاكسنت امريكي كويس وتفهم عليه\n\nالكويزات :\n\nكلها TB وسهلة لو مذاكر السلايدات\n\nالمياجر/ميد:\n\nكومون كل دكتور يحط ٣٣٪؜\n\nالفاينل :\n\nكومون\n\nطريقة التحضير :\n\nيحفظ ارقام الطلاب ويحضر بداية الكلاس وعادي لو تجي بالاخير ممكن يحضرك\n\nاضافات:\n\nالدكتور طيب ومتفهم ويعتبر افضل خيار بعد محسن الحجي في 102", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1507364-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-akimaya/180465/2", "user": "KBSC", "ts": 1552817159000, "tid": 180465, "pn": 2}}]}', 1552817105000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-econ102', 'stk-guest', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f98252", "n": "Dr. Ibrahim M. Algahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON102-201\n\nالتحضير :\nفي نهاية الترم ما أحسه نقص أي أحد عالحضور\n\nطريقة الشرح :\nفي البداية من سلايدات الكتاب ويكتب عليها، وبعدين بحكم مو عاجبة الكتاب جاب سلايدات وهاند-اوتز من عنده وصار يسرح منها وكانت مفيدة\n\nالكويزات :\nعد وأغلط (: .\n١-بوب كويز: يسوي بوب كويز كثير ويكون عبارة عن سؤال واحد ويكون سهل في العادة لكن طبعًا بوب كويز فما راح يقولك عنه من قبل\n٢-تست: غالبًا يكون تشابتر أو ٢، سوا لنا ٣ يكون عبارة عن ١٠ أسئلة+ سؤالين بونص عشان تعوضك لو غلطت.\nوكلها كويزاته اختيارات إلا مرة وحدة سواه رتن\n\nالمياجر:كومن\n\nالفاينلات :كومن\n\nالقريد النهائي:\nB+\nالصوت:\nمرات عنده إزعاج من لاب توبه بشكل غير طبيعي ويحب يطق عالطاولة وهو يسولف وتسمعه واضح الطق فيكون مزعج جدًا، مع إنه في النص الثاني من الترم صار أهدى وقل الإزعاج\nإضافات :\nالدكتور حبيب ومتعاون بشكل كبير وسوا review session قبل الاختبار ويحاول يساعد قد ما يقدر\n\nوهذي كانت درجات سكشنا\nhttp://blob:https://www.stkfupm.com/b93fc553-29e8-4a5e-8a62-a92fc8033c0e", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527609-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ibrahim-m-algahtani/98252/17", "user": "Guest", "ts": 1609843247000, "tid": 98252, "pn": 17}}]}', 1609843247000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mlekon-econ102', 'stk-mlekon', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f98252", "n": "Dr. Ibrahim M. Algahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON102-192\nOnline semester\nالتحضير : يحضر بداية الكلاس وممكن في النص الكلاس يسأل وينادي ويخلي الطلاب يجاوبون بالترتيب اللي ما يرد كم مره يغيبه\n\nطريقة الشرح : الوضع عن بعد فكان كارهه والشرح كان ممل الصراحة لكن اللي بيركز معه بيفهم وما عنده مشكلة يعيد كم مره\n\nالكويزات : سهله جدا وكان كل بداية كلاس تقريبا يعطينا سؤال في الكلاس اللي قبل ويكون سهل مره\n\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: B\nالصوت: جيد\nإضافات : الدكتور حبيب جدا ومتفهم لضروف الطلاب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529314-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ibrahim-m-algahtani/98252/19", "user": "MLEKON", "ts": 1617433144000, "tid": 98252, "pn": 19}}]}', 1617433144000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-zeroal-econ102', 'stk-zeroal', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f98252", "n": "Dr. Ibrahim M. Algahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term211-Econ102\n\nالتحضير : ما يحضر\nطريقة الشرح : من السلايدات اللي عنده, ويعطي شرح من الواقع عشان يقرب لك الصورة. ضروري تسجل معه نوتات بتفيدك\nالكويزات : سهلة, قراءة السلايدات مع فهم كافي\nالمياجر: مافي مياجر فيه مد. بالنسبة لي مذاكرة السلايدات ونوتات نبيل مع فهم تكفي انك تجيب درجة عالية\nالفاينلات : نفس المد\nالصوت: ضعيف يفضل تجلس قدام\nالقريد النهائي: A+\nإضافات : اشوف الدكتور جدا جدا رهيب بعض طلاب شعبتنا يشوفون اكيمايا افضل منه بس اخالفهم. القريدات بالنهاية كانت افرج واخذو افضل 4 كويزات من 7 وافضل هوموركين من 3. +كان فيه اساينمنت بحث قصير صفحة عن العملة الرقمية وسألنا عنهاتوقع كان هدفه يثري الطلاب بالموضوع.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533477-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ibrahim-m-algahtani/98252/23", "user": "zeroal", "ts": 1642226266000, "tid": 98252, "pn": 23}}]}', 1642226266000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-phenomeno-econ102', 'stk-phenomeno', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f98253", "n": "Dr. Hasn H Al-Abandi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : يحضر كل كلاس تقريبا لكنه متعاون في التحضير وحبيب لو تتأخر نص سأعة يدخلك الكلاس ويحضرك بس لا تكثرون منها قدروا اللي يقدركم …\n\nطريقة الشرح : سلايدات ويشرح منها بس صراحة الشرح لك عليه وما تفهم مرة تحتاج إنك ترجع للبيت وتقرا الكتاب عشان تفهم لكن الميزة إن الكلام اللي يشرحه يجيب لك منه في الاختبار يعني يعطيك الزبد …\n\nالكويزات : سهلة بشكل مو طبيعي الله يعطيه ألف عافية كأنه يقول لك تعال خذ فل مارك بالكلاس وورك طبعا الكلاس وورك عليه 20 بالمية 14 كوزات و 6 هومووركات طبعا حراااااام عليك تكون عند العبندي وتاخذ كلاس وورك اقل من 15 الكوزات غالبا في نفس الكلاس يخليها آخر الكلاس وبأول الكلاس يتكلم عن ماتيريال الكوز يعني لو تركز معه بتحل الكوز وتاخذ فل مارك وانت تضحك وأما الهومووركات سهلة جدا اهم شي سلم له أي شي وصدقني بيعطيك حقك وزيادة …\n\nالقريد النهائي: B+\n\nالصوت: واضح بس كلامه بطيء ويمط بالكلام بالعربي أحيانا تنعس وهو ما خلص جملته الله يعطيه الصحة والعافية …*\n\nإضافات : الدكتور يعامل الطلاب كأنهم عياله والله أحيانا أحسه أبو ثاني لي مدرس يقدر الطلاب ويساعدهم لكن بنفس الوقت لازم تساعدونه أنتم يتضايق لما يشوف أحد على جواله ولا مشغول بشي ويلومه بطريقه مؤدبة لانه شخص محترم ويشهد الله إنه غالي علي فقدروا الرجال زي ما يقدركم …*\nالدكتور دمه خفيف وقلبه عسل مع إنه ما يتعمد ينكت بس تحس للحين فيه براءة والله بنفقده كثير هههههههههه لبى قلبه …\nلحد يتبيثر عليه ويقول ساعدني هو من نفسه بيساعد كل الطلاب بس انتم شدوا حيلكم وصدقوني بيعطيكم اللي تستاهلون واكثر بعد انا درست عنده ايكون 102 بترم 121 والله ما اعرف طالب واحد الا مزوده ومعطيه اكثر من حقه انا مجموعي 61 المفروض دي عطاني دي بلص وصديقي 57 عطاه دي من الاخر ما راح يقصر معكم بس شدوا حيلكم لحد ينام ويغيب ويقول ما زودني …\nقبل الميجر والفاينال يسوي هيلب سيشن هذي ضروووووري تحضرها يتكلم عن اشياء تجيك بالنص في الاختبار الفاينال اقل شي تكلم عن نص ماتريال الاختبار يعني لو انك فاهم وما ذاكرت فقط حضرت الا الهلب سشن حقته بتجيب اقل شي نص الدرجة والله ما ابالغ الفاينال كثير اشياء جت بالنص في الاختبار + اللي يحضر يعديه بونص يشيل 3 غيابات طبعا هذا بالعادة لكن بالفاينال ما سوا الحركة …\nبعد ميجر 1 أي طالب ما عنده ولا غياب يزوده درجتين ونص من 100 هذي سواها في الترم الاخير …*\n\nكل اللي اقوله الله يوفقك يا دكتور العبندي وربي مكانه في القلب غالي على هالانسان جدا جدددا وبالتوفيق للجميع …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1165397-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-hasn-h-al-abandi/98253/17", "user": "Phenomeno", "ts": 1358455123000, "tid": 98253, "pn": 17}}]}', 1358455123000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10207-econ102', 'stk-user10207', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f98253", "n": "Dr. Hasn H Al-Abandi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON 102 - Term 142\n\nالتحضير : يحضر أول الكلاس. ماعنده مشكله يحضرك لو تأخرت.\nطريقة الشرح : يشرح من السلايدات. شرحه عادي جداً.\nالكويزات : حوالي ظ¨ كويزات. مستواها صعب.\nالمياجر: صعبه. اختيارات.\nالفاينلات : متوسطه. اختيارات.\nالصوت: مش واضح.\nإضافات :\n- د. العبندي جدا خلوق ومحترم.\n- أسئلته في المياجر صعبه. المشكلة في الإختيارات تحتار بين الاجابات.\n- افرج ميجر ون كان في الاربعينات من ظ،ظ*ظ* والثاني في الخمسينيات.\n- السلايدات ملخبطة وماتصلح للمراجعة ولا للفهم.\n- بالميجر والفاينل يجيب اشياء من برى الكتاب. تحتاج تقرأ في النت على الأشياء الي قالها بالكلاس.\n- يعطي هومورك. مستواها متوسط لسهل. تقدر تجيب درجات فيها.\n- يعطي كلاس مراجعة قبل الإختبار في نفس اليوم.\n- الكلاسوورك يزود.\n- الكلاس ممل.\n- يستخدم البلاكبورد والايميل بشكل ممتاز\n- عنده بونص الي مايغيب ولامرة.\n\nبالتوفيق.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1422826-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-hasn-h-al-abandi/98253/23", "user": "user10207", "ts": 1437478651000, "tid": 98253, "pn": 23}}]}', 1437478651000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-1x1_1-econ102', 'stk-1x1_1', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f98254", "n": "Dr. Usamah Ahmed Uthman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "^^^^^^^^ دام ان محد رد عليكم\n\nانا حضرت عنده كلاس واحد ايكون 202 هالسمستر\nطلب نجيب نوته مدري من وين وما يتعامل مع الكتاب\nاختباراته ومياجره ليست كومن\n\nيرسل رسائل كثيره عالايميل (بعد ما سويت دروب ما زال توصلي ايميلاته)\nالرسائل عباره عن اخبار ومقالات اقتصاديه بالاضافه لمواعيد اختباراته", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1025917-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-usamah-ahmed-uthman/98254/21", "user": "1x1_1", "ts": 1334971130000, "tid": 98254, "pn": 21}}]}', 1334971130000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_assan-econ102', 'stk-_assan', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f98254", "n": "Dr. Usamah Ahmed Uthman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON102 Term 142\n\nالتحضير : أحيانا في البداية أحيانا في النهاية لكن دايم يحضر\n\nطريقة الشرح : عنده نوتة خاصة فيه يحطها على البروجكتر ويشرح عليها (الشرح 7 من 10)\n\nالكويزات : كوز تقريبا كل اسبوع وأسئلته من الـTest Bank (تشتريه من الجمعية)\n\nالمياجر: Multiple Choice من العيار الثقيل\n\nالفاينلات : نفس المياجر (14 تشبتر تقريبا)\n\nالقريد النهائي: B\n\nالصوت: واضح جدا\n\nإضافات : الدكتور يشرح من قلب ويهتم بفهم الطلاب , ويرحب بالأسئلة , صعوبة أسئلة المياجر والفاينلات من الـLanguage أكثر منه من طبيعة السؤال , النوتة حقته بعد لغتها عالية (اهي مأخوذة من كتب أصلا , ارجع لهم يمكن يفيدونك أكثر) , لا تطلع الجوال ولا تنشغل في الكلاس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1424539-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-usamah-ahmed-uthman/98254/34", "user": "_assan", "ts": 1439980926000, "tid": 98254, "pn": 34}}]}', 1439980926000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-plastic_man-econ102', 'stk-plastic_man', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f98264", "n": "Dr. Ashraf Galal Eid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Econ 202\nبدون مجاملة الدكتور اشرف من افضل الدكاترة فكلية الادارة او الجامعة شرييييييح يشرح من قلب لدرجة اني اتذكر شرحه وانا اذاكر فالبيت، رجل عنده مبدأ الامانة فالتدريس يشرحلك كل صغيرة وكبيرة اللي داخل معاك فالمنهج.\nفي مشكلة بسيطة انه يمشي بطيء في الشرح ويكرر الكونسبت زي ماقالو الشباب الين مايدخل المعلومة فراسك ويتش از قوود!\nبالاضافة انه انقليزيته جاااااااامدة، بالنسبة لي استفدت منه فوكاب ومصطلحات البزنس يشرحلك معناها.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p874073-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ashraf-galal-eid/98264/12", "user": "plastic_man", "ts": 1311485867000, "tid": 98264, "pn": 12}}]}', 1311485867000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fin_analyst-econ102', 'stk-fin_analyst', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f98264", "n": "Dr. Ashraf Galal Eid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Econ202\nنفس اللي قالوه الشباب … شرح لايلعى عليه يشرح كل شي بالتفصيل …واذا ركزت معاه مذاكرتك في الغرفة حتكون مرة بسيطة لانك حتتذكر كل شي قاله … صوته عـالي وواضـح …الجلوس في الصف الاول صعب بسبب الصوت\n… احيانا مايحضر ينسى الورقة… واذا حضر نهاية الكلاس…ومافي درجات عالحضور…عدد معين ودي ان…بس مافي احد بالكلاس اخذ دي ان اصلا\nالهوموركات بعد كل تشابتر على الايكون لاب ويخلي الهومورك تقريبا اسبوع مفتوح… بس اذا اتفق على وقت مستحيل يغيره…\nمافي كويزات\nالميدتيرم والفاينل… اسئلة تعتبر سهلة جداً مقارنة بالمجهود اللي يبذله في المحاضرة …وافرج الكلاس اعلى من الكلاسات الثانية…\nبس في النهاية مستحيل يدفك… ولا درجة … حقك بالضبط تاخذه… عشان كذا بعض المدرسين زي اقدم دفو طلابهم شوي وفي النهاية قريداتهم افضل من د.اشرف …\nبس كشرح مااتوقع في افضل منه\nوالـ A+ شوية صعبة في الكلاس مافي احد جابها عندو ترم 102…بس في 2 اخذو A\nونصيحة لاتمسك الجوال قدامه…بيعصب عليك …وخليه عالصامت في الكلاس\nاذا السكشن مفتوح + الوقت مناسب … لاتتردد … اجتهد ورركز معاه بتجيب قريد\n\nالقريد النهائي اعطيه A+ …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p874568-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ashraf-galal-eid/98264/13", "user": "FIN_Analyst", "ts": 1311567028000, "tid": 98264, "pn": 13}}]}', 1311567028000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m7md3804-econ102', 'stk-m7md3804', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f98268", "n": "Dr. Reza Fathollahzadeh Aghdam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت معاه ايكون 202\n\nوكان الكلاس وورك يعتمد على ماي ايكون لاب\nالي فوق 90 % بالايكون لاب يعطيه فل مارك بالكلاس وورك\n\nالتحضير - ناااااااادر جدا\n\nاضافة: اذا بتنزل معاه راح تكسب كورس انجلش زياده 🤠\n\nاعطيه a+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p838678-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-reza-fathollahzadeh-aghdam/98268/7", "user": "m7md3804", "ts": 1304107305000, "tid": 98268, "pn": 7}}]}', 1304107305000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-s.a.l.m.a.n-econ102', 'stk-s.a.l.m.a.n', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f98268", "n": "Dr. Reza Fathollahzadeh Aghdam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده ايكون 202\n\nالتحضير :\nما يهتم فيه مره , مره يحضر و 10 لا\n\nطريقة الشرح :\nسلايدات + يكتب على السبوره ويشرح عليها متى ما دعت الحاجه\n\nالكويزات :\nعلى الايكون لاب\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nB+\n\nالصوت:\nواضح ولغته ممتازه ولهجته واضحه\n\nإضافات :\nالدكتور شرحه ممتاز , يهتم كثير في الايكون لاب وكل الهومووركات عليه واغلب الكويزات على الايكون لاب ,\nاذا ما حصل تنزل عند رحمان , فنزل عند اقدم بدون تردد\n\n🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p977298-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-reza-fathollahzadeh-aghdam/98268/11", "user": "S.a.l.m.a.n", "ts": 1328004380000, "tid": 98268, "pn": 11}}]}', 1328004380000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-blake-econ102', 'stk-blake', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f98268", "n": "Dr. Reza Fathollahzadeh Aghdam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Econ 102 - Macroeconomics\n\nالتحضير :\n\nيحضر عن طريق ورقة تمر ع الفصل ، واحيانا ينسى يحضر\n\nطريقة الشرح :\n\nع السلايدات و ع السبورة ويستخدم امثلة واقعية وجميلة\nيحاول يوصل المعلومة باللي يقدر عليه وخلفيته التاريخية ممتازة\nيحب النقاشات والاسئلة ضمن المادة ، ومستعد يطلع برا المنهج عشان يفيدك ويجاوب عليك\nويعيد الشرح اذا طلبت منه .\nانا شخصيا اشوف شرحه ممتاز\n\nالكويزات :\nمن 3 الى 5 كويزات … اختيارات متعددة ، مستواها متوسط ، يتأخر في تصحيحها\n\nالمياجر:\n\nاذا كان هو الي يحط الميجر فاعرف ان الاسئلة حتعتمد على الفهم وليس الحفظ\nتصحيحه ممتاز ومايظلمك ( في الميجر الرتن طبعا )\nمستوى الاسئلة متفاوت ، في اسئلة سهلة بس قليل ، الاغلب متوسط وصعب\n\nالفاينلات :\nاختيار من متعدد صعوبة متوسطة\n\nالقريد النهائي:\n\nA\nالصوت:\n\nواضح جدا ، اكسنت استرالي سلس ومفهوم لكن واطي ويجيب النعاس\n\nإضافات :\n\nدكتور محترم جدا جدا ، متفهم للطالب ويستشيرنا كثير في مواعيد الميجر والكويزات\nبالنسبة للكلاس وورك … هوة 20 درجة … قسمها كالتالي ( 19 ع الاونلاين هوموورك + 1 ع جميع الكويزات ! ) بالنسبة لي هذا الشي في مصلحة الطالب 100٪\nمايدف درجات او يزود قريدات ، لكن شوي متسامح في التصحيح اذا اثبت في الحل انك فاهم .\nيتواصل عبر البلاكبورد والرسائل ، ويعمل كلاس مراجعة قبل المياجر يحدد فيه رؤوس اقلام تركز عليها ( وكل الي يقولو يجي )\n\nانا فهمت واستمتعت معاه في الكورس وطلعت بقريد ممتاز واتمنى اخذ معاه كورس تاني ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1322478-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-reza-fathollahzadeh-aghdam/98268/12", "user": "blake", "ts": 1390741002000, "tid": 98268, "pn": 12}}]}', 1390741002000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-practice-econ102', 'stk-practice', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f98275", "n": "Dr. Muhammad Saifur Rahman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "احسن دكتور ممكن يمر عليك !!\n\nانا اخذت معاه ايكون101 وذحين منزل ايكون102 معاه برضو ترم 131\n\nدكتووووور بطططططططططططططططططططل\n\nمافي تحضير نهائيا ولا يعترف فيه\n\nشرح متعوب عليه واسلوبه حلو ويشدك\n\nكويزات نسخ لصق من التيست يانك\n\nحبوب وكلاسه ما ينمل منه نهائيا\n\nما يدف في القريدات , حقك بالملي\n\nالله يسعده ويوفقه دنيا واخره", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1251702-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-muhammad-saifur-rahman/98275/20", "user": "Practice", "ts": 1375748601000, "tid": 98275, "pn": 20}}]}', 1375748601000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah_alshiekh-econ102', 'stk-abdullah_alshiekh', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f115367", "n": "Dr. Fazlul Miah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON102-183\n\nالتحضير: آخر المحاضرة، يحظر الجميع لكن في بعض الاحيان يكلم المتاخرين خاصة اذا داخلين بدون كتاب و دفتر\n\nطريقة الشرح: سلايدات ( يشرح والسلايدة الاولى مفتوحة بدون ما يغيرها )، يكتب على السبورة بعض الاحيان\n\nالكويزات: كوزات على بعض الشباتر ( كانت جميعها اختيارات بستثناء آخر كويز رتن ) وبعض الشباتر يخليهم كلاس وورك ( يعطي سؤالين أو ثلاثة لمجموعة من 3/4 طلاب ) وحذف أسوء درجتين\n\nالمياجر: خيارات وصح أو خطأ ( مستواها متوسط الى صعب المياجر أفرجها 60/100 )\n\nالفاينلات: كان بالنسبة ليي أسهل من المياجر\n\nالقريد النهائي: B\n\nالصوت: واضح ولكن يتكلم ببطأ والأغلب ينام أو يطلع يتمشى في نص الكلاس\n\nإضافات:\n\n- لا أعلم عن الاوفس اور لكن يرد على الايميل بعد يوم او يومين هذا اذا رد أصلا\n\n- السلايدات لا يوجد منها أي فائدة لازم تقرأ الكتاب\n\n- عطانا هوموورك واحد بس لأن الكل جاب 100/100", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513378-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-fazlul-miah/115367/21", "user": "Abdullah_Alshiekh", "ts": 1565020803000, "tid": 115367, "pn": 21}}]}', 1565020803000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fhd-econ102', 'stk-fhd', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f115367", "n": "Dr. Fazlul Miah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON 102 - 192\n\nالتحضير : يحضر نهاية الكلاس … من بداية الترم يعلم كل طالب برقمه بالسكشن وينادي بالارقام الايام اللي بعدها.\n\nطريقة الشرح : يفتح السلايدات و يقرأ منها… شرحه يجيب النوم.\n\nالكويزات : خيارات وصح وخطأ.\n\nالمياجر: common .\n\nالقريد النهائي: D.\n\nالصوت: يجيب النوم … مره م انصح فيه الا اذا بتخليها سلف ستدي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522551-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-fazlul-miah/115367/22", "user": "FHD", "ts": 1591093531000, "tid": 115367, "pn": 22}}]}', 1591093531000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-nawafmkz-econ102', 'stk-nawafmkz', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f115367", "n": "Dr. Fazlul Miah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Econ102 - 192\n\nالتحضير : نهاية الكلاس وما عنده مشكلة بالتأخير.\nطريقة الشرح : يشرح من سلايدات الكتاب ويجيب أمثلة من الواقع، أحيانا يكتب على السبورة\nالكويزات : قبل كورونا كويزين mcq متوسطة الصعوبة، فترة كورونا أكثر من كويز بعضها متوسطة وبعضها صعب\nالمياجر: قبل كورونا ميجر واحد ويركز على الكونسبت كثير، فترة كورونا نفس الشي بس اصعب مع سؤال مقالي\nالفاينلات : نفس الميجر\nالصوت: هادي جدا لازم تقعد قدام عشان تركز معه.\nإضافات :\nفي 192 طلب ريبورتين عن تأثير كورونا ترفعها على Turn it in\nسلايدات الكتاب مختصرة جدا تحتاج تذاكر من الكتاب أو مصدر إضافي\nالأمثلة اللي يكتبها شبيهة بكويزاته فمن الأفضل تسجل اللي يركز عليه.\nالدكتور جيد لكن المادة تحتاج شغل.\nالقريد النهائي: C", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525353-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-fazlul-miah/115367/24", "user": "NawafMKZ", "ts": 1599249562000, "tid": 115367, "pn": 24}}]}', 1599249562000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sadguts-econ102', 'stk-sadguts', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f115367", "n": "Dr. Fazlul Miah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON102 - 202\nالدكتور مايحضر لكن يحب ان فيه تفاعل ومشاركة في الكلاس\nشرحه جيد يعني مو الافضل لكن يمشي الحال سلبيته انه يمر على اشياء على انها بسيطة ومايوضحها واحيانا العكس يمر على اشياء سهلة ويعقدها يجيب النوم شوي لكن لو تسال وتصحصح معاه رح تفهم\n\nالدكتور جدا متساعد ويحب ان احد يسال وبالعكس لما تسال يعيد النقطة اكثر من مرة لين تفهمها زين\nبرضو الدكتور يعتمد على الكتاب في الشرح ف سهل تلحق معاه لما تضيع خصوصا في القرافات\nكويزاته كانت متوسطة ل صعبة والي يخليك تحس انها صعبة لما تشوف كويزات الدكاترة الثانين (ابراهيم القحطاني) كانت تافهة والبوب كويز سؤال واحد\nالبوب كويز عند فضلول كانت 5-10 اسئلة وكانت ملغمة تركات\nالجميل انه في نهاية الترم سووا نورملايز للكويزات وزادونا تقريبا درجتين\n\nالهوموركات كانت غريبة معطينا 3 هوموركات اخر اسبوعين وطريقتها يعني مو المتعودين عليه اسئلة و نحل\nكنا نفتح مواقع ونجيب احصائيات عالمية للدول ونطبق الي فهمناه من الكورس عليها\nكانت جميلة صراحة لكن حشرنا بالوقت وتصحيحه كان يعطي الكل نفس الدرجة يعني طبيعي تخش تشوف كل الكلاس 8/10 الا واحد 7 مثلا\nف غالبا ماكان يصحح\n\nمجملا خيار لاباس فيه لكن لو القحطاني موجود افضل بكثير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531530-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-fazlul-miah/115367/27", "user": "SadGuts", "ts": 1630068522000, "tid": 115367, "pn": 27}}]}', 1630068522000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-jafar_15-econ102', 'stk-jafar_15', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f167104", "n": "Dr. Fahad Al-Subaie", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON 102-171\nالتحضير : بداية الكلاس يحضر بنفسه\n\nطريقة الشرح : يشغل السلايدات ويبدا يشرح. شرحه كله كونسبت. شي اسمه حل مسائل انسسسسسسسسسى\n\nالكويزات : ماعطانا ولا كويز\n\nالمياجر: كومن، اسئلة خيارات ورتن والكوردنتير كان الدكتور محسن الحجي\n\nالفاينلات : كومن وكان MCQ لانه صار اخر ايام الفاينلات وجانا من TB الكتاب القديم مو نفس كتابنا\n\nالصوت: واضح\n\nإضافات : الدكتور كشرح للكونسبت واضح ومفهموم، لكن المشكلة المياجر والفاينل يكون اعتماد الكوردنتير على حل المسائل اكثر من الكونسبت فصار الوضع ملخبط بالنسبة لنا.\nاعطانا حدود 8 واجبات طوييييييلة ويشرط عليك ماتكون منسوخة وتحطها في Turnitin، يقول لو كانت منسوخة ابشر بF ومايعلمك عنه. في نهاية الترم اعطانا 3 واجبات بونص.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485844-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fahad-al-subaie/167104/10", "user": "Jafar_15", "ts": 1515518049000, "tid": 167104, "pn": 10}}, {"id": "stk-dr-f178388", "n": "Dr. Khaled Al-Otaibi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON 102 - 172\n\nالتحضير :\nيوميا بداية الكلاس، مايقبل الميكب الا اذا كلمته بالايميل قبل الكلاس ورد عليك.\n\nطريقة الشرح :\nيفتح السلايدات ويشرح عليها، ومرات يشرح على السبورة بدون السلاديات ويمديك تكتب وراه. بشكل عام شرحه من متوسط الى ممتاز والدكتور توه شباب وكان ثاني ترم له فهو يتطور كل فترة. يشرح الكونسبت اول شي، بعدين يحل مسائل على الشابتر اذا كان فيه\n\nالكويزات :\nمتنوعة، مرات يجيب صعب مرات سهل مرات متوسط، وتكون اغلبها رتن. يمكن مرة او مرتين جاب خليط بين الرتن والخيارات.\nوعطانا 10 كويزات واخذ احسن 5 منهم.\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالصوت:\nللاسف شبه ضعيف.\n\nإضافات :\nالدكتور جدا محترم ويحاول يتساعد مع الكل، بشكل عام انصح فيه وبقوة. اتوقع مستقبلًا بتصير سكاشنه اول سكاشن تقفل غرارًا على ماتياس والقحطاني والحجي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498421-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-al-otaibi/178388/4", "user": "Jafar_15", "ts": 1535628594000, "tid": 178388, "pn": 4}}]}', 1515518049000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-makkahboy-econ102', 'stk-makkahboy', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f178388", "n": "Dr. Khaled Al-Otaibi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON102 - 172\n\nالتحضير: في بداية الكلاس يحضر بالأسامي\n\nطريقة الشرح: في البداية كان يستخدم السبورة ويكتب والشباب ينقلون وراه بعدين بدأ يستخدم السلايدات ويستخدم السبورة وقت الحاجة إذا سألته عن شغلة\n\nالكويزات: اختبرنا 10 كويزات أخذ أفضل 5 الله يجزاه خير . سهلة لو أنه حاضر معاه الكلاسات ومتابع معاه\n\nالتصحيح : يعطيك حقك ومايظلم\n\nالمياجر: كومن\n\nالفاينل: كومن\n\nالهوموركات : لا يوجد\n\nالصوت: متوسط يميل للمنخفض… وعموما الكلاس اللي كنا فيه صغير فالصوت مسموع للكل\n\nإضافات:\n- يسمح بالتأخير وماتكلم أبد ويحضرك بنهاية الكلاس\n- يمسح بالميك اب بس لازم تعطيه خبر من بدري ويكون لديك سبب مقنع (بعض الأحيان لو نمت عن الكلاس تقدر تحضر ويمشيك)\n- ما اظلم الدكتور لكني اشعر انه واحدة من اثنين: إما انه فاهم ومايوصل بطريقة ممتازة او انه فاهم تسليك صراحة\nلأنه مايجاوب بشكل كافي وعميق لبعض أسئلة الطلاب.\n-الحق لله: الدكتور متعاون وحبيب وروحه شبابية ويحاول يفهمك قدما يقدر\n-يرد عالإيميلات بسرعة ومايتأخر بالمجمل\n- يدفك بنهاية السمستر قريد\n- كويزاته كانت سهلة جدا بس تحضر وتتابع معاه وتحلها وأنت مغمض\n- بالمقارنة مع البقية: اشوفه أفضل الموجود\n\nالقريد النهائي: B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493678-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-al-otaibi/178388/3", "user": "makkahboy", "ts": 1528085192000, "tid": 178388, "pn": 3}}]}', 1528085192000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hassan.a-econ102', 'stk-hassan.a', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f180465", "n": "Dr. Mohammad Akimaya", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Econ102- 192\n\nالتحضير : في الدوام الحضوري كان في بداية الكلاس واحياناً ينسى التحضير وياخذه في وسط الكلاس او نهايته وفي الدوام عن بعد ياخذ التحضير من البلاكبورد\n\nالشرح: يشرح من سلايدات خاصة فيه ويرفعها على البلاكبورد، الدكتور يميل إلى استخدام لغة الارقام في شرحه ممكن بسبب انه شهادته البكالوريس في الهندسة الكهربائية\n\nالكويزات: متوسطة الصعوبة\n\nاضافات: حقيقة لا انصح في التسجيل معه لعدة اسباب راح اذكرها ، الدكتور من بعد ماتحولت الدراسة عن بعد اصبح شديد وصارت طلباته كثيرة\nالرجال كرفنا للأمانة كويزات و قروب بروجيكت وبريزنتشين للبروجيكت و 3 اسايمنت ( واجب طويل نوعاً ما) ، ١٩٢ صادف حدوث الازمة الاقتصادية والدكتور كرفنا على اساس انه نستفيد من الوضع الحالي لأنه المادة فيها مواضيع تتكلم عن الركود الاقتصادي والازمات\n\nنظامه كان يعطينا كويز على كل تشابتر ولازم تجيب نص درجة الكويز في كل كويز تختبره علشان تعدّي الكورس ( 50% من درجة الكويز) والاسايمنت والبروجيكت والبريزنتيشن لازم تجيب في كل واحد منهم 60% من الدرجة الخاصة فيه ، ‏اذا ماجبت الدرجة المطلوبة وش راح يصير ؟ الدكتور بيعطيك فرصة ثانية بيحط لك revision للكويز او الاسايمنت اللي ماحققت فيه الدرجة المطلوبة واذا ماحققت الدرجة المطلوبة للمرة الثانية راح تأخذ F , يعني لو مجموع درجاتك في المادة فوق 60 (D grade) وعندك كويز جبت فيه اقل من الدرجة المطلوبة راح يعطيك الدكتور revision واذا ماجبت الدرجة المطلوبة للمرة الثانية راح تاخذ F وهذا نظام ظالم للأسف ، هل فيه اخذ F ؟ ، للأمانة ماعندي معلومة ولكن هذا نظامه وكلامه لنا يوم اخذت المادة،\n\nملاحظة اخيرة: الكلام فوق هذا وجهة نظري في الدكتور في الفصل الدراسي 192 قد يتغير الدكتور للأسوء او الافضل يفضل انك تسأل عنه اكثر عند تسجيلك للمادة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525360-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-akimaya/180465/3", "user": "Hassan.A", "ts": 1599307985000, "tid": 180465, "pn": 3}}]}', 1599307985000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ali20-econ102', 'stk-ali20', 'ECON 102', 'doc', '{"docs": [{"id": "stk-dr-f180465", "n": "Dr. Mohammad Akimaya", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON102 - Term 203 (online)\n\nالتحضير : كان ياخذ التحضير من البلاكبورد وكان متساهل نوعاً ما، كل مانسأله كم عندنا غياب يقول دونت ووري\n\nطريقة الشرح : يعرض صفحة بيضا ويشرح عليها بخط يده، خط يده سيئ لكن ركز معه بالكلام ورح تفهم\n\nالصوت : واضح يتكلم بلكنة امريكية\n\nالكويزات : متوسطة الصعوبة\n\nالميد/ الفاينل : متوسطين الصعوبة، إذا كنت تركز معه وتراجع الكتاب مرح تواجه مشكلة فيهم\n\nإضافات : الدكتور خلوق ومتساعد حذف لنا اسوء كويز واسوء هوموورك.\nإذا فيه أفضل منه لاتسجل عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531506-econ102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-akimaya/180465/5", "user": "Ali20", "ts": 1629989261000, "tid": 180465, "pn": 5}}]}', 1629989261000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
